pts=[(0,3),(0,8),(0,9),(0,19),(1,4),(1,5),(1,11),(1,12),(1,20),(2,6),(2,10),(2,13),(2,17),(3,11),(3,22)]
# hull x=col, y=row
p=sorted(set((c,r) for r,c in pts))
def cross(o,a,b): return (a[0]-o[0])*(b[1]-o[1])-(a[1]-o[1])*(b[0]-o[0])
lo=[]
for x in p:
 while len(lo)>=2 and cross(lo[-2],lo[-1],x)<=0:lo.pop()
 lo.append(x)
up=[]
for x in reversed(p):
 while len(up)>=2 and cross(up[-2],up[-1],x)<=0:up.pop()
 up.append(x)
hull=lo[:-1]+up[:-1]
hull
